CREATE TABLE "stock_candle" (
	"stock_candle_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"stock_id"	BIGINT		NOT NULL,
	"interval"	VARCHAR(10)		NOT NULL,
	"candle_time"	TIMESTAMP		NOT NULL,
	"open_price"	INTEGER		NOT NULL,
	"high_price"	INTEGER		NOT NULL,
	"low_price"	INTEGER		NOT NULL,
	"close_price"	INTEGER		NOT NULL,
	"volume"	BIGINT		NOT NULL
);

CREATE TABLE "execution" (
	"execution_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"buy_order_id"	BIGINT		NOT NULL,
	"sell_order_id"	BIGINT		NOT NULL,
	"stock_id"	BIGINT		NOT NULL,
	"price"	BIGINT		NOT NULL,
	"quantity"	BIGINT		NOT NULL,
	"executed_at"	TIMESTAMP		NOT NULL
);

CREATE TABLE "settlement" (
	"settlement_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"execution_id"	BIGINT		NOT NULL,
	"account_id"	BIGINT		NOT NULL,
	"side"	SMALLINT		NOT NULL,
	"amount"	BIGINT		NOT NULL,
	"trade_date"	TIMESTAMP		NOT NULL,
	"status"	SMALLINT		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL,
	"settlement_date"	TIMESTAMP		NOT NULL,
	"processed_at"	TIMESTAMP		NULL
);

COMMENT ON COLUMN "settlement"."trade_date" IS 'executed_at와 동일 값';

CREATE TABLE "stock" (
	"stock_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"code"	VARCHAR(25)		NOT NULL,
	"name"	VARCHAR(50)		NOT NULL,
	"market"	VARCHAR(25)		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL
);

CREATE TABLE "account" (
	"account_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"member_id"	BIGINT		NOT NULL,
	"cash"	BIGINT		NOT NULL,
	"available_cash"	BIGINT		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL,
	"updated_at"	TIMESTAMP		NOT NULL
);

CREATE TABLE "order_book" (
	"order_book_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"order_id"	BIGINT		NOT NULL,
	"stock_id"	BIGINT		NOT NULL,
	"side"	SMALLINT		NOT NULL,
	"price"	BIGINT		NOT NULL,
	"remaining_quantity"	BIGINT		NOT NULL,
	"priority_at"	TIMESTAMP		NOT NULL
);

CREATE TABLE "position" (
	"position_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"account_id"	BIGINT		NOT NULL,
	"stock_id"	BIGINT		NOT NULL,
	"quantity"	INTEGER		NOT NULL,
	"average_price"	INTEGER		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL,
	"updated_at"	TIMESTAMP		NOT NULL
);

CREATE TABLE "orders" (
	"order_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"account_id"	BIGINT		NOT NULL,
	"stock_id"	BIGINT		NOT NULL,
	"side"	VARCHAR(4)		NOT NULL,
	"type"	VARCHAR(6)		NOT NULL,
	"price"	BIGINT		NULL,
	"quantity"	BIGINT		NOT NULL,
	"status"	VARCHAR(20)		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL,
	"updated_at"	TIMESTAMP		NOT NULL
);

COMMENT ON COLUMN "orders"."side" IS 'Side string: BUY, SELL';
COMMENT ON COLUMN "orders"."type" IS 'OrderType string: LIMIT, MARKET';
COMMENT ON COLUMN "order_book"."side" IS 'Side ordinal: 0=BUY, 1=SELL';
COMMENT ON COLUMN "settlement"."side" IS 'Side ordinal: 0=BUY, 1=SELL';
COMMENT ON COLUMN "settlement"."status" IS 'ExecutionStatus ordinal: 0=PENDING, 1=COMPLETED, 2=FAILED';

CREATE TABLE "member" (
	"member_id"	BIGINT GENERATED BY DEFAULT AS IDENTITY	NOT NULL,
	"email"	VARCHAR(254)		NOT NULL,
	"password"	VARCHAR(255)		NOT NULL,
	"name"	VARCHAR(15)		NOT NULL,
	"created_at"	TIMESTAMP		NOT NULL
);

ALTER TABLE "member" ADD CONSTRAINT "UK_MEMBER_EMAIL" UNIQUE (
	"email"
);

ALTER TABLE "stock" ADD CONSTRAINT "UK_STOCK_CODE" UNIQUE (
	"code"
);

